package com.lianxibu.site.config;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import com.lianxibu.site.service.jobs.*;import com.lianxibu.site.repository.jobs.JdbcBacklogMutationWitness;import com.lianxibu.site.domain.jobs.BacklogHistoryTelemetry;
import java.time.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicReference;import org.junit.jupiter.api.*;import org.springframework.boot.test.context.runner.ApplicationContextRunner;
class BacklogMonitoringConfigurationTest {
 String[] flags(){return new String[]{"site.ops.backlog-monitoring.enabled=true","site.browser.enabled=true","site.content.enabled=true","site.articles.enabled=true","site.sources.enabled=true","site.execution.enabled=true"};}
 ApplicationContextRunner runner(){var executor=mock(ScheduledExecutorService.class);when(executor.scheduleAtFixedRate(any(Runnable.class),anyLong(),anyLong(),eq(TimeUnit.NANOSECONDS))).thenReturn(mock(ScheduledFuture.class));return new ApplicationContextRunner().withUserConfiguration(BacklogMonitoringConfiguration.class).withBean(javax.sql.DataSource.class,()->mock(javax.sql.DataSource.class)).withBean(org.springframework.transaction.PlatformTransactionManager.class,()->mock(org.springframework.transaction.PlatformTransactionManager.class)).withBean(DispatchReadinessService.class,()->mock(DispatchReadinessService.class)).withBean("backlogMonitoringExecutor",ScheduledExecutorService.class,()->executor).withPropertyValues(flags()).withPropertyValues("SITE_BACKLOG_MONITOR_RESOURCE=fictional-backlog");}
 @Test void missingAndDisabledFlagsProduceNoWitnessOrSampler(){new ApplicationContextRunner().withUserConfiguration(BacklogMonitoringConfiguration.class).run(c->{assertNull(c.getStartupFailure());assertTrue(c.getBeansOfType(BacklogMonitoringConfiguration.Batch.class).isEmpty());});for(int disabled=0;disabled<6;disabled++){var values=flags();values[disabled]=values[disabled].replace("true","false");new ApplicationContextRunner().withUserConfiguration(BacklogMonitoringConfiguration.class).withPropertyValues(values).run(c->{assertNull(c.getStartupFailure());assertTrue(c.getBeansOfType(BacklogMonitoringConfiguration.Witness.class).isEmpty());assertTrue(c.getBeansOfType(ScheduledExecutorService.class).isEmpty());});}}
 @Test void enabledNativeFactoryIsColdAndExternalHealthyFactsCannotEnter(){runner().withBean(BacklogHistoryTelemetry.Api.class,()->()->{fail("external healthy facts must not enter native factory");return null;}).run(c->{assertNull(c.getStartupFailure());var batch=c.getBean(BacklogMonitoringConfiguration.Batch.class);assertEquals(1,batch.cycles().size());assertInstanceOf(BacklogHistoryObservationService.class,batch.nativeFacts());assertTrue(c.getBean(BacklogMonitoringConfiguration.Loop.class).isRunning());assertTrue(c.getBean(BacklogMonitoringConfiguration.Witness.class).isRunning());assertEquals("BacklogMonitoringBatch[redacted]",batch.toString());assertEquals(Integer.MIN_VALUE+100,c.getBean(BacklogMonitoringConfiguration.Witness.class).getPhase());verifyNoInteractions(c.getBean(javax.sql.DataSource.class),c.getBean(org.springframework.transaction.PlatformTransactionManager.class),c.getBean(DispatchReadinessService.class));});}
 @Test void missingReadinessInvalidIdentityAndScopeMismatchFailClosed(){for(String resource:List.of("","x".repeat(65),"fictional\tresource"))runner().withPropertyValues("SITE_BACKLOG_MONITOR_RESOURCE="+resource).run(c->assertNotNull(c.getStartupFailure()));new ApplicationContextRunner().withUserConfiguration(BacklogMonitoringConfiguration.class).withBean(javax.sql.DataSource.class,()->mock(javax.sql.DataSource.class)).withBean(org.springframework.transaction.PlatformTransactionManager.class,()->mock(org.springframework.transaction.PlatformTransactionManager.class)).withPropertyValues(flags()).withPropertyValues("SITE_BACKLOG_MONITOR_RESOURCE=fictional-backlog").run(c->assertNotNull(c.getStartupFailure()));var ds=mock(javax.sql.DataSource.class);var tx=mock(org.springframework.transaction.PlatformTransactionManager.class);var ready=mock(DispatchReadinessService.class);try(var scope=JdbcBacklogMutationWitness.open(ds,Clock.systemUTC())){for(var key:List.of(new OperationalRuleEngine.Key("OPS-08","java","fictional-backlog"),new OperationalRuleEngine.Key("OPS-01","collector","fictional-backlog")))assertThrows(IllegalArgumentException.class,()->BacklogMonitoringConfiguration.create(ds,tx,ready,scope,key,Clock.systemUTC(),System::nanoTime));assertThrows(IllegalStateException.class,()->BacklogMonitoringConfiguration.create(mock(javax.sql.DataSource.class),tx,ready,scope,new OperationalRuleEngine.Key("OPS-01","java","fictional-backlog"),Clock.systemUTC(),System::nanoTime));}verifyNoInteractions(ds,tx,ready);}
 @Test void witnessShutdownDoesNotDisableAFreshRuntimeAndRequiresNewScopeAfterStop(){var ds=mock(javax.sql.DataSource.class);var clock=mock(Clock.class);var first=new BacklogMonitoringConfiguration.Witness(ds,clock);assertFalse(first.isRunning());first.start();assertTrue(first.isRunning());first.stop();assertThrows(IllegalStateException.class,first::start);var next=new BacklogMonitoringConfiguration.Witness(ds,clock);next.start();first.close();assertTrue(next.isRunning());assertThrows(IllegalStateException.class,()->JdbcBacklogMutationWitness.open(ds,clock));next.close();try(var fresh=JdbcBacklogMutationWitness.open(ds,clock)){assertNotNull(fresh);}verifyNoInteractions(ds,clock);}
 @Test void cycleFailureDoesNotStarveOtherSourceAndNextMinuteCanRetry(){var first=mock(BacklogMonitoringCycle.class);var second=mock(BacklogMonitoringCycle.class);when(first.tick()).thenThrow(new IllegalStateException("fictional unavailable")).thenReturn(BacklogMonitoringCycle.Outcome.SAMPLED);var batch=new BacklogMonitoringConfiguration.Batch(List.of(first,second),mock(BacklogHistoryObservationService.class),mock(JdbcBacklogMutationWitness.Scope.class));var executor=mock(ScheduledExecutorService.class);var tick=new AtomicReference<Runnable>();var future=mock(ScheduledFuture.class);when(executor.scheduleAtFixedRate(any(Runnable.class),anyLong(),anyLong(),eq(TimeUnit.NANOSECONDS))).thenAnswer(a->{tick.set(a.getArgument(0));assertEquals(TimeUnit.SECONDS.toNanos(50),(long)a.getArgument(1));assertEquals(TimeUnit.SECONDS.toNanos(60),(long)a.getArgument(2));return future;});var loop=new BacklogMonitoringConfiguration.Loop(batch,executor,Clock.fixed(Instant.parse("2026-01-01T00:00:10Z"),ZoneOffset.UTC));loop.start();verify(first).start();verify(second).start();tick.get().run();assertTrue(loop.hasFailure());verify(second).tick();tick.get().run();assertFalse(loop.hasFailure());verify(first,times(2)).tick();verify(second,times(2)).tick();loop.stop();tick.get().run();verify(first,times(2)).tick();verify(first).stop();verify(second).stop();verify(future).cancel(true);assertFalse(loop.isRunning());}
 @Test void shutdownCallbackWaitsAndRejectedScheduleNeverPretendsRunning()throws Exception{var cycle=mock(BacklogMonitoringCycle.class);var batch=new BacklogMonitoringConfiguration.Batch(List.of(cycle),mock(BacklogHistoryObservationService.class),mock(JdbcBacklogMutationWitness.Scope.class));var executor=mock(ScheduledExecutorService.class);var tick=new AtomicReference<Runnable>();var entered=new CountDownLatch(1);var release=new CountDownLatch(1);var done=new CountDownLatch(1);when(executor.scheduleAtFixedRate(any(Runnable.class),anyLong(),anyLong(),eq(TimeUnit.NANOSECONDS))).thenAnswer(a->{tick.set(a.getArgument(0));return mock(ScheduledFuture.class);});when(cycle.tick()).thenAnswer(a->{entered.countDown();assertTrue(release.await(2,TimeUnit.SECONDS));return BacklogMonitoringCycle.Outcome.STOPPED;});var loop=new BacklogMonitoringConfiguration.Loop(batch,executor,Clock.systemUTC());var pool=Executors.newSingleThreadExecutor();try{loop.start();pool.submit(()->tick.get().run());assertTrue(entered.await(1,TimeUnit.SECONDS));loop.stop(done::countDown);assertEquals(1,done.getCount());assertThrows(IllegalStateException.class,loop::start);release.countDown();assertTrue(done.await(1,TimeUnit.SECONDS));}finally{release.countDown();pool.shutdownNow();}when(executor.scheduleAtFixedRate(any(Runnable.class),anyLong(),anyLong(),eq(TimeUnit.NANOSECONDS))).thenThrow(new RejectedExecutionException());assertThrows(RejectedExecutionException.class,loop::start);assertFalse(loop.isRunning());}
}
